use std::{io::{Read,Write},net::TcpListener,sync::mpsc::{self,Receiver,SyncSender},time::Duration};use serde_json::Value;
#[path="../../src/donation.rs"]mod qr;
pub struct Request{pub command:Option<Value>,pub reply:SyncSender<Result<Value,String>>}
fn token()->std::io::Result<String>{let path=super::data_dir().join("web-token");if let Ok(s)=std::fs::read_to_string(&path){let s=s.trim();if s.len()==64&&s.bytes().all(|b|b.is_ascii_hexdigit()){return Ok(s.into())}return Err(std::io::Error::other("Invalid web-token"));}let mut bytes=[0;32];std::fs::File::open("/dev/urandom")?.read_exact(&mut bytes)?;let s=bytes.iter().map(|b|format!("{b:02x}")).collect::<String>();use std::os::unix::fs::OpenOptionsExt;std::fs::OpenOptions::new().write(true).create_new(true).mode(0o600).open(path)?.write_all(s.as_bytes())?;Ok(s)}
fn equal(a:&str,b:&str)->bool{a.len()==b.len()&&a.bytes().zip(b.bytes()).fold(0,|x,(a,b)|x|(a^b))==0}
fn answer(s:&mut std::net::TcpStream,code:&str,kind:&str,body:&str){let _=write!(s,"HTTP/1.1 {code}\r\nContent-Type: {kind}\r\nContent-Length: {}\r\nCache-Control: no-store\r\nX-Content-Type-Options: nosniff\r\nX-Frame-Options: DENY\r\nReferrer-Policy: no-referrer\r\nContent-Security-Policy: default-src 'self'; script-src 'self' 'unsafe-inline'; style-src 'self' 'unsafe-inline'; img-src 'self' blob:; frame-ancestors 'none'; connect-src 'self'\r\nConnection: close\r\n\r\n{body}",body.len());}
pub fn start()->std::io::Result<Receiver<Request>>{let token=token()?;let listener=TcpListener::bind("0.0.0.0:18766")?;let(tx,rx)=mpsc::sync_channel::<Request>(8);std::thread::spawn(move||{for stream in listener.incoming(){let Ok(mut stream)=stream else{continue};let Ok((method,path,auth,body))=super::request(&mut stream) else{answer(&mut stream,"400 Bad Request","text/plain","Invalid request");continue};if method=="GET"&&path=="/"{answer(&mut stream,"200 OK","text/html; charset=utf-8",include_str!("../web/index.html"));continue}if !equal(&auth,&format!("Bearer {token}")){answer(&mut stream,"401 Unauthorized","application/json",r#"{"error":"Access key required"}"#);continue}if method=="GET"&&path=="/donation"{let addr=std::fs::read_to_string(super::data_dir().join("donation-address.txt")).unwrap_or_default();let addr=addr.trim();let matrix=qr::ADDRESSES.iter().position(|a|*a==addr).map(|i|qr::MATRICES[i]);answer(&mut stream,"200 OK","application/json",&serde_json::json!({"address":addr,"matrix":matrix}).to_string());continue}let command=if method=="GET"&&path=="/status"{None}else if method=="POST"&&path=="/command"{match serde_json::from_slice(&body){Ok(v)=>Some(v),Err(_)=>{answer(&mut stream,"400 Bad Request","application/json",r#"{"error":"Invalid JSON"}"#);continue}}}else{answer(&mut stream,"404 Not Found","text/plain","Not found");continue};let(reply,receive)=mpsc::sync_channel(1);if tx.try_send(Request{command,reply}).is_err(){answer(&mut stream,"503 Service Unavailable","application/json",r#"{"error":"Busy"}"#);continue}match receive.recv_timeout(Duration::from_secs(2)){Ok(Ok(v))=>answer(&mut stream,"200 OK","application/json",&v.to_string()),Ok(Err(e))=>answer(&mut stream,"400 Bad Request","application/json",&serde_json::json!({"error":e}).to_string()),Err(_)=>answer(&mut stream,"503 Service Unavailable","application/json",r#"{"error":"Service timeout"}"#)}}});Ok(rx)}
